import re, gzip
src = open("EVDCTRL.h", encoding="utf-8").read().replace("\r", "")
html = re.search(r'R"HTML\((.*)\)HTML"', src, re.S).group(1).encode("utf-8")
gz = gzip.compress(html, 9)
BANNER = (
    "#pragma once\n"
    "// ============================================================================\n"
    "//  EVDCTRL_GZ.h -- GENERATED FILE.  DO NOT EDIT THIS FILE.\n"
    "//\n"
    "//  Source:    EVDCTRL.h  (the raw HTML / CSS / JS dashboard page)\n"
    "//  Generator: gen_gz.py  (or gen_gz.bat on Windows)\n"
    "//\n"
    "//  HOW TO UPDATE THE DASHBOARD\n"
    "//    1. Edit EVDCTRL.h.\n"
    "//    2. Regenerate this file:\n"
    "//           python gen_gz.py\n"
    "//       (or run gen_gz.bat)\n"
    "//    3. Verify the size printed matches EVDCTRL_HTML_GZ_LEN below.\n"
    "//    4. Rebuild and reflash the server.\n"
    "//\n"
    "//  FAILURE MODE IF YOU FORGET STEP 2\n"
    "//    The build succeeds, the server boots, '/' serves the PREVIOUS\n"
    "//    dashboard version. There is NO compiler warning. If a dashboard\n"
    "//    edit is not taking effect, the cause is almost always that\n"
    "//    EVDCTRL.h was edited but EVDCTRL_GZ.h was not regenerated.\n"
    "//\n"
    "//  Boot-time reminder: setup_serial() logs the gzip length so the\n"
    "//  serial monitor shows which dashboard build is running.\n"
    "// ============================================================================\n"
)
with open("EVDCTRL_GZ.h", "w") as f:
    f.write(BANNER)
    f.write("#include <Arduino.h>\n")
    f.write("static const uint8_t EVDCTRL_HTML_GZ[] PROGMEM = {\n")
    for i in range(0, len(gz), 16):
        f.write("  " + ",".join("0x%02x" % b for b in gz[i:i+16]) + ",\n")
    f.write("};\n")
    f.write("static const size_t EVDCTRL_HTML_GZ_LEN = %d;\n" % len(gz))
print("raw", len(html), "gz", len(gz))